CREATE TABLE PROTOCOLLO_SEQUENZE 
(
  IDCOMUNE VARCHAR2(6) NOT NULL 
, FLUSSO VARCHAR2(1) NOT NULL 
, CODICESEQUENZA VARCHAR2(50) NOT NULL 
, CONSTRAINT PROTOCOLLO_SEQUENZE_PK PRIMARY KEY 
  (
    IDCOMUNE 
  , FLUSSO 
    )
  ENABLE 
);
COMMENT ON TABLE PROTOCOLLO_SEQUENZE IS 'Gestito solo da Protocollo InsielMercato, vengono passati dei codici sequenza diversi in base al flusso, arrivo o partenza, in precedenza era usato il parametro MODALITA_SEQUENZA della verticalizzazione PROTOCOLLO_INSIELMERCATO che gestiva solo un flusso,con la creazione di questa tabella il parametro diventa obsoleto.';

